INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4981866, 391, '/rTJRWO9zHcB29JecTXHg0wUa4Xs.jpg', 'Stylized sepia-toned poster art of the Man With No Name (Clint Eastwood''s Joe), cigarillo clenched in his mouth, squinting beneath a wide-brimmed hat with a revolver raised beside his face, draped in his poncho against a stark white background.', 'claude-sonnet-5-5')
