INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4981867, 391, '/ApjqczKExVLnHqnXEkibbBTbyTc.jpg', 'Squinting under a wide-brimmed hat with a cheroot clenched in his mouth, Clint Eastwood''s poncho-clad Stranger (Joe) stands against a sun-bleached rock wall, a weathered, steely-eyed picture of laconic menace in the harsh Spanish-Mexican frontier light.', 'claude-sonnet-5-5')
