INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 201974, 11878, '/zd7mu6dJKxkVtBdXqlEQ9W3msKl.jpg', 'Perched on a wooden watchtower, Toshirō Mifune''s grinning Sanjuro looks down on the dirt street, where two rival gangs of swordsmen face off in the gang war he has cleverly engineered, in stark black-and-white.', 'claude-sonnet-5-5')
