INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 201975, 11878, '/5BBwSVytssbFuSPZE4DtJVhROjN.jpg', 'Toshirō Mifune''s ronin Sanjuro stands in the village street with a hand thoughtfully on his chin and his swords at his hip, while a small older man beside him raises a finger as if offering advice, set against pine trees and tiled rooftops.', 'claude-sonnet-5-5')
