INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 201976, 11878, '/ykB6zxo2m6NFBwfyx7E4qmRTax6.jpg', 'Back to back in a weathered wooden street, Toshirō Mifune''s wry, stubble-chinned ronin Sanjuro rests his chin on his sword hilt, smirking, while a grim, hooded older man, likely the tavern keeper Gonji, stares gravely the other way in black-and-white tension.', 'claude-sonnet-5-5')
