INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 201977, 11878, '/vRlVjroFOHIG3LVWB8SHL62tdkt.jpg', 'Toshirō Mifune''s wary ronin Sanjuro, crest on his kimono, reaches across a tavern table while Tatsuya Nakadai''s pistol-holding Unosuke and a scowling henchman watch tensely beside a sake bottle, in stark black-and-white menace.', 'claude-sonnet-5-5')
