INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 201979, 11878, '/3GeYS26DLJTjYPemg1ZaLSiKVO2.jpg', 'Stylized gray-and-gold artwork of Toshirō Mifune as the nameless ronin Sanjuro Kuwabatake, his intense, wary eyes fixed forward as his sleeved arm thrusts toward the camera, evoking the tense, lone-swordsman menace of Yojimbo.', 'claude-sonnet-5-5')
