INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 201980, 11878, '/4isrrCx2NhQfaOPQsYJNLRNWIA0.jpg', 'Stylized artwork of Toshirō Mifune as the nameless ronin Sanjuro Kuwabatake, scowling and mid-draw with his sword arm raised, his weathered, stubbled face lit in smoky gold and gray tones that convey menace and gritty defiance.', 'claude-sonnet-5-5')
