INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 201981, 11878, '/f29CHmfi2G6Sc332nl7xUoKFcPf.jpg', 'In the climactic showdown on the dusty village street, Tatsuya Nakadai''s pistol-wielding Unosuke, in a striped kimono and scarf, squares off against Toshirō Mifune''s Sanjuro, who grips his sword hilt before weathered wooden storefronts in tense black-and-white stillness.', 'claude-sonnet-5-5')
