INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 201982, 11878, '/aEs0VfrcNAzZ99QrFGTyhfuVzmK.jpg', 'Toshirō Mifune''s wary ronin Sanjuro Kuwabatake rubs his chin and glances sideways, sword at his hip, before a rough stone wall in the tense, dusty village, sizing up the rival gangs with sly, calculating suspicion.', 'claude-sonnet-5-5')
