INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 201983, 11878, '/8KuxVrDRUAECiC7CyKDgPBe7nXX.jpg', 'Perched atop a wooden watchtower beside a hanging bell, Toshirō Mifune''s wandering ronin Sanjuro stands with sword in hand against a stark white sky, smirking as he watches the rival gangs prepare to clash below.', 'claude-sonnet-5-5')
