INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 201984, 11878, '/3IkEsASsXppMs5EFFm5S0IShDTG.jpg', 'Grinning broadly, Toshirō Mifune''s wandering ronin Sanjuro Kuwabatake pauses on a bare dirt path with his sword shouldered, glancing back over his shoulder amid dry winter brush in this stark black-and-white scene of his lone journey.', 'claude-sonnet-5-5')
