INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 201985, 11878, '/yNHz8xIszm2KF7JUxpkINoYyO7f.jpg', 'Toshirō Mifune as the ronin Sanjuro strides squinting through swirling dust in the windswept street, his topknot disheveled and sword at his hip, radiating wary, battle-ready menace in stark black-and-white.', 'claude-sonnet-5-5')
