INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 201986, 11878, '/f0CDZYyLGi5i0ONhK4sdYzOxXfs.jpg', 'Seen from behind in stark black and white, the wandering ronin Sanjuro (Toshirō Mifune) stands in a field of dry mulberry stalks, his crested kimono dark against the pale sky as he glances aside, calm and watchful.', 'claude-sonnet-5-5')
