INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 201987, 11878, '/d9oeJvEQReDWM0TARWCDc0Lwdde.jpg', 'In stark black-and-white, Toshirō Mifune''s wary ronin Sanjuro Kuwabatake fixes a hard, sidelong stare past the camera, his sword hilt rising at the frame''s edge, as he sizes up the danger in the feuding yakuza town.', 'claude-sonnet-5-5')
