INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 201988, 11878, '/2ICQ9tA47siW9hgy4Kclm6hZdiv.jpg', 'Toshirō Mifune''s nameless ronin, later calling himself Sanjuro Kuwabatake, strides along a dirt road past small stone markers and a bare mulberry field, with hazy mountains behind him, grinning with a wary, swaggering air.', 'claude-sonnet-5-5')
