INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 201992, 11878, '/55YGdXSFkW8CC1O6MkkDhx80T7D.jpg', 'Toshirō Mifune''s wandering ronin Sanjuro sits slumped on a tatami floor beside a shoji window, arms folded and head bowed, katana over his shoulder, in a quiet, wary moment of brooding stillness amid the town''s gang war.', 'claude-sonnet-5-5')
