INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 201993, 11878, '/jWbEsNRGjrxPlpvgtkcoadIzoh0.jpg', 'Perched on a rickety wooden watchtower against a blank sky, Toshirō Mifune''s wry ronin Sanjuro grins with amusement as he looks down on the village''s rival gangs, savoring the chaos he has set in motion.', 'claude-sonnet-5-5')
