INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249163, 346, '/sJNNMCc6B7KZIY3LH3JMYJJNH5j.jpg', 'Six of the seven samurai stand in a line amid tall barley under a bright sky, with Kikuchiyo (Toshirō Mifune) shouldering a long spear beside Kambei and the others, all gazing watchfully toward the horizon in this stoic black-and-white image.', 'claude-sonnet-5-5')
