INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249164, 346, '/qvZ91FwMq6O47VViAr8vZNQz3WI.jpg', 'In a low-angle black-and-white group portrait against a cloudy sky, the seven samurai stand armed in the grass, with Toshirō Mifune''s Kikuchiyo in front, sword on his shoulder, as Kambei and the others look resolutely off-frame.', 'claude-sonnet-5-5')
