INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249165, 346, '/mzI1JXm8sX5fia3ifPS2jGPUh2n.jpg', 'In the final downpour of Seven Samurai, a battered samurai kneels in churned mud among dropped swords and spears, while weary comrades in rain-soaked gear stand over him, the thatched village behind them, after the climactic battle against the bandits.', 'claude-sonnet-5-5')
