INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249168, 346, '/6AdFHG5fTtcdmyJQdFbnSgiauv2.jpg', 'Under a wide, cloudy sky, kneeling villagers with upright spears pay solemn tribute at the funeral mounds on the hilltop, while the surviving samurai stand together at the crest, mourning their fallen comrades after the battle in Seven Samurai.', 'claude-sonnet-5-5')
