INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249169, 346, '/qEF0JCQUHBN0VSQOa17zfC9SUAb.jpg', 'In a ferocious black-and-white close-up from Seven Samurai, Toshirō Mifune''s wild Kikuchiyo charges toward the camera in a studded helmet and fur-trimmed armor, mouth open in a battle roar amid the blurred chaos of the village defense.', 'claude-sonnet-5-5')
