INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249170, 346, '/yXZGgqjlM93PdNEbtfU05CKGVYh.jpg', 'In the film''s climactic downpour, a bare-shouldered, mud-spattered Kikuchiyo (Toshirō Mifune) lurches forward through the churning mud with sword in hand, wounded and exhausted, while another fighter struggles nearby amid the chaos of the final battle against the bandits.', 'claude-sonnet-5-5')
