INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249171, 346, '/5cCJtYijBUvluQqc5kW0rBvuRXl.jpg', 'In a tight black-and-white close-up, Kikuchiyo (Toshirō Mifune) glares wide-eyed and scowling from under a battered helmet and chainmail neck guard, rain-slicked and fierce, likely amid the village''s final battle.', 'claude-sonnet-5-5')
