INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249173, 346, '/fANI8642Hb5Aw6G7j4toTpnQRBT.jpg', 'Crouched shoulder to shoulder in tense black-and-white, a cluster of samurai and spear-bearing defenders in armor and headbands peer sideways at an unseen threat, braced for the bandit assault on the village in Kurosawa''s Seven Samurai.', 'claude-sonnet-5-5')
