INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249174, 346, '/yOxE4IL9oQc8OQu3AwJdKCmLDwN.jpg', 'In a dim, shadowy hut in the village, a wide-eyed, startled peasant in a patterned robe stares at a weathered, bearded old man in profile, probably the elder Gisaku, in a tense black-and-white close-up from Seven Samurai.', 'claude-sonnet-5-5')
