INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249175, 346, '/bTGczYh4GSFjAPRrIb9oCi7CkSq.jpg', 'Under a stormy sky in stark black and white, the seven samurai stand grouped on a hillside, with a bare-chested, sword-shouldering Kikuchiyo (Toshirō Mifune) at the front, glaring into the distance as Kambei, Katsushirō and the others hold back, ready to defend the village.', 'claude-sonnet-5-5')
