INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249179, 346, '/v6sVRa03SBAoZP5ZLbTWTb1vk28.jpg', 'On a windswept hilltop path edged with wildflowers, Kikuchiyo, a long sword slung over his shoulder, faces the shaven-headed Kambei, who holds a straw hat, in a tense, stark black-and-white standoff beneath a vast cloudy sky.', 'claude-sonnet-5-5')
