INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249182, 346, '/3pccDdGWL9udZyW4gFVxUnJ0hRJ.jpg', 'Standing before a crowd of villagers with their backs to the camera, the samurai of Seven Samurai hold bowls of rice in a stark black-and-white scene, with a bearded Kikuchiyo, played by Toshirō Mifune, at center, in a tense moment of mingled gratitude and unease.', 'claude-sonnet-5-5')
