INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249190, 346, '/fJJdDGqacaqzIRetySeVn6h4Qe8.jpg', 'Low-angle black-and-white group portrait of the seven samurai standing in tall grass against a smoky, cloud-streaked sky, with Toshirō Mifune''s wild Kikuchiyo in front, sword over his shoulder, as Kambei and the others gather behind with weary resolve.', 'claude-sonnet-5-5')
