INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249191, 346, '/ubDfi7d5wyw6heRbxODeyUOHKKy.jpg', 'A young man in a plain kimono lies on his back among white chrysanthemums, gazing upward in a quiet, dreamlike moment, most likely Katsushirō in the flower meadow where he meets Shino, shot in soft black-and-white.', 'claude-sonnet-5-5')
