INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249194, 346, '/oWYl7CuCOUXGlQJ7SqHgDYZoOQo.jpg', 'Seen from behind on a steep hillside, the samurai and villagers pause above the small mountain hamlet they have come to defend, its thatched roofs nestled among terraced fields in a quiet, watchful black-and-white vista.', 'claude-sonnet-5-5')
