INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249195, 346, '/lXGUrywwRmZi6JtNxGf2e3ZWi44.jpg', 'Shino, played by Keiko Tsushima, lies wide-eyed among blooming daisies in the mountain meadow, hands pressed to her mouth, in a tender, startled black-and-white close-up from her secret romance with the young samurai Katsushirō.', 'claude-sonnet-5-5')
