INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249196, 346, '/e8i5CXCH4FLp21e0oFf474KGORF.jpg', 'Kyuzo, the stoic master swordsman played by Seiji Miyaguchi, rests against a tree trunk in a meadow of wildflowers, his sheathed katana across his lap, in a quiet, solitary moment of stillness in black and white.', 'claude-sonnet-5-5')
