INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249198, 346, '/kN3It3VB9SiTPDJH1SvfNs2DbYf.jpg', 'Kikuchiyo, played by Toshirō Mifune, stands defiantly in a shadowy forest with an oversized sword propped on his shoulder, his rough, half-open kimono and fierce, squinting glare conveying the wild bravado of the self-proclaimed samurai.', 'claude-sonnet-5-5')
