INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249199, 346, '/g5ScZQ6iu5Clk3PwCrWcnLxW40v.jpg', 'The seven samurai, swords at their belts, gather on a flower-strewn hillside path as they travel toward the village, while a lone figure follows in the distance and the group talks in a tense, wary mood.', 'claude-sonnet-5-5')
ON DUPLICATE KEY UPDATE CAPTION=VALUES(CAPTION), TIM_UPDATED=CURRENT_TIMESTAMP;
INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249200, 346, '/dgzTmu3Ag28dcb75DLbJT1xkSUf.jpg', 'Gathered on a wooden floor, the seven samurai laugh warmly together as Kikuchiyo leans forward over a scroll, in a rare moment of camaraderie and levity before the village''s defense in Kurosawa''s black-and-white epic.', 'claude-sonnet-5-5')
