INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249202, 346, '/jEW72wSauXOUCohq3SihFbyZnsa.jpg', 'Two armored figures crouch in the undergrowth in Seven Samurai, probably Kikuchiyo, bare-shouldered with a sword and a helmet, facing a floral-robed companion in a headband, locked in a tense, wary exchange before the bandit assault.', 'claude-sonnet-5-5')
