INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 249207, 346, '/u7ts0bTxx3dK8hqyWXx0ZJzgInP.jpg', 'In the village''s dirt lane, a bare-legged samurai, likely Kikuchiyo, stands with a spear-like pole outstretched while peasants hold bamboo spears and train under his direction, as another figure raises a pole from a wooden platform in the background.', 'claude-sonnet-5-5')
