INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4981914, 391, '/cezAeTyLeEIgaFNgIYU1gw9oSAY.jpg', 'Seen from behind, Clint Eastwood''s poncho-clad Stranger rides his horse across the stony, sunbaked ground toward a whitewashed adobe building, with arid brown hills looming beyond, in the lonely, tense stillness of his approach to the Mexican frontier town in A Fistful of Dollars.', 'claude-sonnet-5-5')
